import{_ as t,c as a,o as r,a5 as d}from"./chunks/framework.CUh81O5y.js";const g=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"devices/api/glossary.md","filePath":"devices/api/glossary.md"}'),o={name:"devices/api/glossary.md"};function s(i,e,c,n,h,l){return r(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[d('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Term</th><th>Description</th></tr></thead><tbody><tr><td><a href="/docs/pr/18/devices/api/sdks/toit/">Toit</a></td><td>A programming language designed for IoT devices, which we provide a <a href="/docs/pr/18/devices/api/sdks/toit/">high level SDK</a> for.<br>[<a href="https://toitlang.org/" target="_blank" rel="noreferrer">Toit official website</a>]</td></tr><tr><td>ESP32</td><td>A popular low-cost microcontroller with built-in WiFi and Bluetooth, used in some Lightbug devices.<br>[<a href="https://en.wikipedia.org/wiki/ESP32" target="_blank" rel="noreferrer">ESP32 on Wikipedia</a>]</td></tr><tr><td>Message</td><td>A packet of communication sent between clients, using the <a href="/docs/pr/18/devices/api/protocol/">Lightbug protocol</a>.</td></tr><tr><td><a href="/docs/pr/18/devices/api/protocol/prefix">Prefix</a></td><td>Optional bytes before a message to make it easier to see in a byte stream.<br><code>0x4c, 0x42</code> which is <code>LB</code> in ascii.</td></tr><tr><td>Header</td><td>The first part of the message that contains metadata about a message.<br>Length, type, method, and other generic metadata or instruction.</td></tr><tr><td>Payload</td><td>The primary data that is being sent in a message.</td></tr><tr><td><a href="/docs/pr/18/devices/api/protocol/headers">Header field</a> type</td><td>A field type <code>uint8</code> that is used within header data.<br>These are generally reused across all message types.</td></tr><tr><td>Payload field type</td><td>A field type <code>uint8</code> that is used within payload data.<br>These are generally specific to a message type.<br>See <a href="/docs/pr/18/devices/api/messages/">messages</a>.</td></tr><tr><td>bBytes</td><td>A byte array that represents a length and that amount of data in bytes.<br>The length prefix is a <code>uint8</code> (1 byte) for data type IDs 0–127, or a little-endian <code>uint16</code> (2 bytes) for data type IDs 128–255.<br>A bByte entry for a sub-128 field might be <code>3 9 9 9</code>, where <code>3</code> is the length, and <code>9 9 9</code> is the data.<br> A bByte entry for a field with ID 128 or greater might be <code>3 0 9 9 9</code>, where <code>3</code> is the length, and <code>9 9 9</code> is the data.<br> See <a href="/docs/pr/18/devices/api/protocol/structure#bbytes">structure</a>.</td></tr></tbody></table>',2)]))}const f=t(o,[["render",s]]);export{g as __pageData,f as default};
